    INSERT INTO tbl_setup_item (item_name_id, item_class_id, item_brand_id, unit_of_measure_id,
        item_model, catalogue_year, item_code, item_tangibility_type, is_stop_selling, price)
    SELECT
        (SELECT TOP 1 id FROM tbl_setup_item_name            WHERE code = N'ELEC'),
        (SELECT TOP 1 id FROM tbl_setup_item_class           WHERE code = N'HW'),
        (SELECT TOP 1 id FROM tbl_setup_item_brand           WHERE code = N'NB'),
        (SELECT TOP 1 id FROM tbl_setup_item_unit_measurement WHERE code = N'PC'),
        N'LS CIRCUIT BREAKER ABN203, 125A 3 POLE 600V', NULL, RIGHT('0000' + CAST(@next AS NVARCHAR(20)), CASE WHEN @next > 9999 THEN LEN(CAST(@next AS NVARCHAR(20))) ELSE 4 END),
        N'TRD', 0, 0.0;
    SET @id = SCOPE_IDENTITY(); SET @next = @next + 1; SET @inserted = @inserted + 1;
    INSERT INTO tbl_setup_item_trade_type (item_id, trade_type_id)
    SELECT @id, id FROM tbl_setup_item_type WHERE code = N'TRD';
    INSERT INTO tbl_setup_item_additional_specs (based_id, long_description)
    VALUES (@id, N'LS CIRCUIT BREAKER ABN203, 125A 3 POLE 600V');
END
