SELECT 'tbl_setup_item' AS [table], COUNT(*) AS rows_now FROM tbl_setup_item;
SELECT 'tbl_setup_item_trade_type', COUNT(*) FROM tbl_setup_item_trade_type;
SELECT 'tbl_setup_item_additional_specs', COUNT(*) FROM tbl_setup_item_additional_specs;
SELECT 'items with no brand resolved' AS check_, COUNT(*) AS n FROM tbl_setup_item WHERE item_brand_id IS NULL;
SELECT 'items with no class resolved', COUNT(*) FROM tbl_setup_item WHERE item_class_id IS NULL;
SELECT 'items with no uom resolved', COUNT(*) FROM tbl_setup_item WHERE unit_of_measure_id IS NULL;
GO
